const normalizeLocale = (locale?: string | null): DungeonLibraryNameLocale => {
  const language = String(locale ?? "en").toLowerCase().split(/[-_]/)[0];
  return language === "de" || language === "hu" || language === "cs" ? language : "en";
};

export const getLocalizedDungeonName = (dungeonId: number, locale?: string | null): string | undefined => {
  const key = String(dungeonId);
  const activeLocale = normalizeLocale(locale);
  const activeNames = DUNGEON_LIBRARY_NAMES[activeLocale] as DungeonLibraryNames;
  const englishNames = DUNGEON_LIBRARY_NAMES.en as DungeonLibraryNames;
  return activeNames.dungeonNames[key] ?? englishNames.dungeonNames[key];
};

export const getLocalizedDungeonFloorName = (
  dungeonId: number,
  floorPosition: number,
  locale?: string | null,
): string | undefined => {
  const key = `${dungeonId}:${floorPosition}`;
  const activeLocale = normalizeLocale(locale);
  const activeNames = DUNGEON_LIBRARY_NAMES[activeLocale] as DungeonLibraryNames;
  const englishNames = DUNGEON_LIBRARY_NAMES.en as DungeonLibraryNames;
  return activeNames.floorNames[key] ?? englishNames.floorNames[key];
};
